operation.add:
{% if module_hide_qty_lite_status is not defined or module_hide_qty_lite_status %}
<!-- FlexExt Hide Quantity Field Lite -->
<style>
#input-quantity:not([type="hidden"]),
input[name="quantity"]:not([type="hidden"]),
label[for="input-quantity"] {
    display: none !important;
}
#button-cart {
    display: block !important;
    visibility: visible !important;
    opacity: 1 !important;
    {% if module_hide_qty_lite_full_width is not defined or module_hide_qty_lite_full_width %}
    width: 100% !important;
    border-radius: 6px !important;
    {% endif %}
}
</style>
<script type="text/javascript">
$(document).ready(function() {
    var $qty = $('#input-quantity, input[name="quantity"]');
    if ($qty.attr('type') !== 'hidden') {
        $qty.hide();
        $('label[for="input-quantity"]').hide();
    }
    $('.qty-stepper, .btn-number, .quantity-stepper').hide();
    $('#button-cart').prev('br').hide();
    var $btn = $('#button-cart');
    if ($btn.length) {
        $btn.show().css({'display': 'block', 'visibility': 'visible', 'opacity': '1'});
        {% if module_hide_qty_lite_full_width is not defined or module_hide_qty_lite_full_width %}
        $btn.css({'width': '100%', 'border-radius': '6px'});
        {% endif %}
    }
});
</script>
<!-- /FlexExt Hide Quantity Field Lite -->
{% endif %}
